#include <stdio.h>
#include <string.h>

int main() {
    char s[1005];
    if (scanf("%s", s) != 1) return 0;
    int len = strlen(s);
    for (int i = 0; i < len; ) {
        char ch = s[i];
        int count = 0;
        while (i < len && s[i] == ch) { count++; i++; }
        printf("%c%d", ch, count);
    }
    printf("\n");
    return 0;
}

